#!/usr/bin/env node
/*
 * Exports the demo data generated by assets/js/data.js to server/database/seeders/demo-data.json,
 * so the Laravel DemoSeeder loads exactly the same people, stores, products, targets, shifts and sales.
 * Usage: node tools/export-demo-data.js
 */
const fs = require('fs');
const path = require('path');
const vm = require('vm');
const root = path.join(__dirname, '..');
const sandbox = { window: {}, console };
vm.runInNewContext(fs.readFileSync(path.join(root, 'assets/js/data.js'), 'utf8'), sandbox);
const D = sandbox.window.Data;
const state = D.exportState();
const out = path.join(root, 'server/database/seeders/demo-data.json');
fs.writeFileSync(out, JSON.stringify({ today: D.TODAY, ...state }));
console.log(`wrote ${out} (${Math.round(fs.statSync(out).size / 1024)} KB)`);
